function t(t){if(!t)return"-";let e;if("number"==typeof t||"string"==typeof t&&/^\d+$/.test(t.trim())){const n=Number(t);e=new Date(n>1e12?n:1e3*n)}else e=new Date(t);return e.toLocaleString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"})}function e(t){if(t<60)return t+"分钟";const e=Math.floor(t/60),n=t%60;return n>0?`${e}h ${n}m`:`${e}h`}function n(t){return t?t>=1e4?(t/1e4).toFixed(1)+"万":t.toLocaleString():"0"}export{n as a,e as b,t as f};
